exec(open("batches/hiv_common.py").read())
# HIV 2022 part 1, pp.18-29. Summary of major changes: cell text from the PDF ruled grid (grid_extract.py), structure checked on the page images.
# The PDF prints the summary twice (printed pp.7-9 and again 10-12, from the middle of Chapter 7); chapters 1-6 and the start of 7 come from
# the first printing, the rest from the second (cleaner: it resolves an "Error! Reference source not found" to Table 7.4).
HP = "Chapter 1: Introduction > 1.2 Summary of Major Changes"
DUP = "The Summary of Major Changes is printed twice in the PDF (printed pp.7-9, then pp.10-12 restart partway through Chapter 7). The second printing differs slightly: it says VL monitoring can move to annual 'after 2 consecutive suppressed VL results 6 months apart' where the first says 'taken at least 6 months apart', and it fixes a broken cross-reference ('Error! Reference source not found' -> Table 7.4)."
ITEMS = [
 D("fig-1.1-patient-centred-care", 20, "Chapter 1: Introduction > 1.1 Background > Figure 1.1: Patient-centred care as a tool to end AIDS by 2030", "Figure 1.1: Patient-centred Care as a tool to end AIDS by 2030", [],
   "Diagram of the 2025 AIDS targets around PLHIV and communities at risk at the centre.\nCentre: PLHIV and communities at the risk at the centre, surrounded by six 95% targets: 95% use combination prevention; 95% of PLHIV know their status; 95% of PLHIV who know their status initiate treatment; 95% on treatment are virally suppressed; 95% coverage of services for eliminating vertical transmission; 95% of women access SRH services.\nLeft (societal enablers): <10% of countries have punitive laws and policies; <10% experience gender inequality or violence; <10% experience stigma and discrimination.\nRight: 90% of PLHIV and people at risk are linked to people-centred and context-specific integrated services.",
   footnotes=["Adapted from: https://www.unaids.org/en/resources/presscentre/featurestories/2021/july/20210721_2025-aids-targets"]),
 T("tbl-1.1-how-to-use", 20, "Chapter 1: Introduction > 1.1 Background > Table 1.1: How to use these guidelines", "Table 1.1 How to Use These Guidelines", ["0018"],
   [r("Content type", "Marker used in the guidelines")],
   [r("Updates and changes", "Orange arrows icon"), r("Outside reference", "Books icon"), r("Important messages", "Green box"), r("Tools", "Purple box"), r("Dosing information", "Brown box")],
   source_flags=["The markers are icons and coloured boxes; described in words here. Column headings added."]),
 B("box-1.2-summary-ch1", 21, HP + " > Chapter 1: Introduction", "Summary of major changes: Chapter 1 (Introduction)", ['0019'],
   "Chapter 1: Introduction – major changes in the 2022 guidelines:\n- Background\n- Usage of guideline\n- Summary of major changes",
   flags=[], pages=list(range(21, 21+1))),
 B("box-1.2-summary-ch2", 21, HP + " > Chapter 2: Prevention of HIV", "Summary of major changes: Chapter 2 (Prevention of HIV)", [],
   "Chapter 2: Prevention of HIV – major changes in the 2022 guidelines:\n- Change of terminology from serodiscordant to sero-different couples\n- Event-driven oral TDF-based ED-PrEP as a 2+1+1 regimen can be offered to HIV-negative clients assigned male at birth (and not on exogenous hormones), as an alternative dosing schedule from daily oral PrEP, to prevent HIV transmission from sexual exposure.\n- The Dapivirine ring may be offered as an additional prevention choice for cis-gender women at substantial risk of HIV as part of a combination prevention approach.\n- An HIV post-exposure prophylaxis (PEP) regimen with three drugs is preferred for all persons accidentally, occupationally, sexually or otherwise exposed to HIV.\n- DTG is recommended as the preferred third drug for HIV PEP.\n- When available, ATV/r, DRV/r, LPV/r and RAL may be considered as alternative third drug options for PEP in adults.",
   flags=[], pages=list(range(21, 21+1))),
 B("box-1.2-summary-ch3", 21, HP + " > Chapter 3: HIV Testing Services", "Summary of major changes: Chapter 3 (HIV Testing Services)", ['0020', '0021'],
   "Chapter 3: HIV Testing Services – major changes in the 2022 guidelines:\n- HIV testing services should be offered to all clients with unknown HIV status at every point of contact in the health facility and community settings.\n- The HIV testing screening tool will be used to determine how often a client with a previous HIV-negative result will need to be re-tested for HIV.\n- Client-initiated HIV testing services and provider-initiated HIV testing services are two approaches to be used at the entry point to HIV prevention, care, and treatment services.\n- Targeted testing, including index testing (testing the family members and sexual partners of people diagnosed with HIV) and social network testing (testing the sexual partners and peers of HIV-positive key populations), are the preferred methods of testing.\n- To encourage contacts of index clients with unknown HIV status to be tested, every HIV-positive client will be given information on client notification options, either through passive referral or assisted HIV partner notification services.\n- HIV Self-test kits/Oraquick can be distributed at the health facility level and performed privately in the client’s home or facilitated by a healthcare worker in a private setting at a health facility. The age of consent for HIVST is 16 years.\n- All HIV tests conducted must follow the National HIV Testing Algorithm for children and adults. Referral and linkages to prevention or care and treatment services should be provided to both negative and positive clients, respectively.\n- Rapid tests (Determine™ and UniGold™) are antibody tests that can be used to definitively diagnose adults and children aged 18 months or older. DNA PCR is used to diagnose children less than 18 months of age and for inconclusive results according to the National HIV Testing Algorithm.\n- Retesting for verification - all clients with positive HIV results presenting for ART initiation should be re-tested, with a second specimen, preferably with a different tester, before ART initiation.\n- DNA PCR has replaced Clearview tests as the tie breaker for inconclusive results when testing for HIV.\n- Quality assurance for counselling for HTS providers, supervisors and laboratory/National HTS Program is outlined in Table 3.15.",
   flags=[], pages=list(range(21, 22+1))),
 B("box-1.2-summary-ch4", 22, HP + " > Chapter 4: Referral and Linkages", "Summary of major changes: Chapter 4 (Referral and Linkages)", ['0022'],
   "Chapter 4: Referral and Linkages – major changes in the 2022 guidelines:\n- All clients testing HIV positive must be proactively linked (escort client or set an appointment) for ART initiation\n- Health care worker who identifies the HIV-positive client should ensure linkage of the client\n- All clients with positive HIV results presenting for ART initiation should be re-tested before they are initiated on ART preferably by a different tester.\n- All people living with HIV are eligible to start ART regardless of CD4 count or WHO staging to promote early ART initiation\n- Newly diagnosed HIV clients should be checked in the CMIS if they are genuinely new positive before they are linked for treatment.\n- All clients newly initiated on ART must be enrolled on enhanced counselling to support their adherence and retention\n- All clients found to be returning to care must be linked back to care as indicated in the extended LCM SOP\n- All clients testing HIV-negative should be linked to combination HIV prevention services\n- Combination HIV prevention is an approach that seeks to achieve maximum impact on preventing new HIV infections.\n- Bidirectional communication between facilities and communities is important to improve HIV linkages either to prevention or care and treatment.\n- Active tracing of clients who have disengaged from care must be routinely done for all clients",
   flags=[], pages=list(range(22, 22+1))),
 B("box-1.2-summary-ch5", 22, HP + " > Chapter 5: Basic Care Package for HIV-Positive Individuals", "Summary of major changes: Chapter 5 (Basic Care Package for HIV-Positive Individuals)", ['0023', '0024'],
   "Chapter 5: Basic Care Package for HIV-Positive Individuals – major changes in the 2022 guidelines:\n- ART initiation may be offered in the community for clients who have mild or moderate immunosuppression and no current or previous history of clinical, immunologic or virologic treatment failure\n- For clients who initiate ART with a baseline CD4 count >350cell/mm³, and show good clinical response, there is no value added by doing a follow-up CD4 count at 6 months\n- For clients who initiate ART with a CD4 count <350cell/mm³, CD4 monitoring should be done by 6 months and 12 months after ART initiation. Once the client has 2 consecutive undetectable viral loads, CD4 monitoring can be stopped. If treatment failure is suspected, resume CD4 monitoring until the client has an undetectable viral load.\n- After one year on ART, clinically well adult clients can receive ART refills every 3-6 months, and clinical assessments every 6 months.\n- Children who have been receiving ART for more than one year and are established on ART, and older than 2 years should not be considered to have AHD and are eligible for MMD\n- The basic HIV chronic care package includes routine screening and management of non-communicable diseases, mental health and palliative care services as well as assessment of and offering of COVID-19 vaccination.\n- Less intensive (up to 3MMD) differentiated service delivery may also be offered to children at least 2 years of age, pregnant and breastfeeding women, clients with controlled comorbidities and key population",
   flags=[], pages=list(range(22, 23+1))),
 B("box-1.2-summary-ch6", 23, HP + " > Chapter 6: TB/HIV Collaborative Activities & Advanced HIV Disease", "Summary of major changes: Chapter 6 (TB/HIV Collaborative Activities & Advanced HIV Disease)", ['0025', '0026'],
   "Chapter 6: TB/HIV Collaborative Activities & Advanced HIV Disease – major changes in the 2022 guidelines:\n- TB screening should be done for all PLHIV at every health care visit of contact with a healthcare worker using the national recommended 4 symptom TB screening tool including children and adolescents. Presumptive TB is defined as a patient reporting any one of the TB for symptoms\n- For PLHIV with presumptive TB, offer rapid ART initiation while rapidly investigating for TB, with close follow-up within 7 days to initiate TB treatment if TB is confirmed\n- X-pert MTB/RIF is a recommended TB diagnostic test and TB LF LAM is recommended diagnostic TB test for selected groups among PLHIV. See section 6.1.3\n- C-Reactive Protein should be used for ART naïve patients as an additional TB screening tool.\n- TB initiation may be considered at ART initiation in patients without advanced HIV disease (clinically well)\n- 3 months of Rifapentine/Isoniazid (3HP) is the recommended TPT option except in pregnant and lactating women and children\n- Delay ART initiation for PLHIV with TB meningitis, Cryptococcal meningitis or Histoplasmosis\n- For TB patients other than TB meningitis, who are diagnosed with HIV, ART initiation should be started as soon as possible, preferably within 14 days of initiating TB treatment.\n- AHD patients with CD4 cell counts < 100 cells/mm³ should be screened for Cryptococcal Antigenemia\n- All children younger than 5 years who are not already receiving ART and clinically stable) are considered to have advanced HIV disease. Children who have been receiving ART for more than one year and are established on ART, and older than 2 years should not be considered to have AHD and are eligible for MMD\n- CSF CrAg is recommended for diagnosis of Cryptococcal meningitis\n- Single dose Liposomal Amphotericin B is recommended for the induction phase of cryptococcal meningitis treatment\n- Histoplasmosis screening and treatment are recommended for patients with AHD and symptomatic histoplasmosis\n- Fluconazole prophylaxis may be discontinued after 12 months of antifungals once the CD4 count is >100 cells/mm³ and virally suppressed",
   flags=[], pages=list(range(23, 23+1))),
 B("box-1.2-summary-ch7", 23, HP + " > Chapter 7: Adult Antiretroviral Therapy", "Summary of major changes: Chapter 7 (Adult Antiretroviral Therapy)", ['0027', '0028', '0037', '0038'],
   "Chapter 7: Adult Antiretroviral Therapy – major changes in the 2022 guidelines:\n- ART may be initiated in the community for clinically well clients who are willing to follow up at a health facility of their choice.\n- ART should be (re)initiated from the entry point where the patient tests positive followed by referral to the ART clinic for ongoing management follow-up\n- Baseline Random blood sugar, Height, Weight, BMI, and screening for NCD family history are required for all patients initiating ART\n- Delay ART initiation for PLHIV with TB meningitis, Cryptococcal meningitis\n- Clients initiating ART and at high risk of metabolic complications should be routinely monitored for metabolic adverse drug reactions\n- For patients on haemodialysis, the ART prescribed should be taken after a dialysis session.\n- Due to high pre-treatment NNRTI resistance in Eswatini, ART initiation on NNRTI-based regimens should be used as a last resort, particularly in treatment-experienced patients\n- Clients on an NNRTI-based regimen should be transitioned to a DTG-based regimen. Transition can occur regardless of VL, however, take note of viremia for future reference and to ensure adherence issues are addressed while switching\n- Point of care(POC) viral load testing may be done for ART patients who need expedited decision-making. See section 7.10.2 for priority clients for POC Viral Load testing.\n- VL should be measured by 6 months after ART initiation to confirm virologic response to ART. After 2 consecutive suppressed VL results 6 months apart, VL monitoring can be done annually and patient-guided into a DSD model of their choice.\n- Receipt of a high VL test result in a patient on an NNRTI-based regimen should trigger an immediate regimen switch while undergoing SUAC. Clients should be called to come to the facility within the next 7 days to begin SUAC. See Figure 7.4 for the management protocol.\n- Two consecutive viral load test results above ≥1000 copies/mL taken three months apart with adequate adherence support should be used to determine virological failure when using plasma or dried blood spot specimens.\n- Do not keep patients on a failing regimen for a long time without appropriate action\n- Regimen switch to the second or third line should be done through a multidisciplinary approach\n- Use of DBS VL for clients presenting outside of normal phlebotomy hours and in children\n- Remnant blood samples of all clients with high viral load may be stored to be used for surveillance purposes to guide program and policy changes.\n- Engagement of social workers, psychologists and psychiatry nurses for clients with identified poor adherence\n- HIV drug resistance testing (genotype) should be requested for all clients with two consecutive viral load results above 1000copies/ml:\n   - while on drug-sensitive TB treatment during second-line treatment\n   - while taking a 2nd line regimen\n   - while taking a DTG-based ART first- or second-line regimen\n- Contact email for HIVDR support changed to:snapthirdline@mohcoag.org.\n- Patients with renal insufficiency, active viral hepatitis and on a third-line regimen should be managed at a doctor managed ART clinic",
   flags=[DUP], pages=list(range(23, 27+1))),
 B("box-1.2-summary-ch8", 27, HP + " > Chapter 8: Prevention of Mother to Child Transmission of HIV (PMTCT)", "Summary of major changes: Chapter 8 (Prevention of Mother to Child Transmission of HIV (PMTCT))", ['0029', '0030', '0031', '0039', '0040', '0041'],
   "Chapter 8: Prevention of Mother to Child Transmission of HIV (PMTCT) – major changes in the 2022 guidelines:\n- As part of efforts to achieve the elimination of MTCT (eMTCT), all HIV-negative pregnant and lactating women should be offered PrEP using the OPT OUT approach\n- Pregnant and lactating women on PrEP should be retested according to the PrEP retesting schedule.\n- All HIV-negative pregnant women not on PrEP should be re-tested every 2 months (aligned with the ANC scheduled visits) with the most optimal time point for retesting during the third trimester visit (34 weeks Gestation).\n- All HIV-negative lactating women should be re-tested at 6 weeks, 14 weeks, 6 months, 9 months, 12 months, 15 months and 18 months aligned with the mother-baby pair (MBP) schedule.\n- For pregnant women with inconclusive results after HTS; conduct Nucleic Acid Amplification Tests (NAAT) and initiate ART immediately while waiting for NAAT results\n- Virally suppressed mothers enrolled in a DSD model may continue to do so provided that all VLs are done on time (First ANC and 34 weeks).\n- Viral load monitoring schedules specific for pregnant and lactating women are:\n   - All newly initiated ART clients should receive the first viral load test 3 months after starting ART and thereafter align with the ANC VL schedule. If the next VL test date falls after delivery, then align with PNC/MBP VL schedule.\n   - Women on ART enrolling for ANC should receive a viral load test on their first ANC contact. A subsequent viral load test should be conducted at 34 weeks of gestation.\n   - VL testing is compulsory for all women on ART at 6 weeks post-delivery regardless of the previous viral load date. Subsequent VL tests during lactation are done every 6 months until the cessation of breastfeeding.\n- Early infant diagnosis:\n   - All HIV-exposed infants must be tested using DNA PCR at birth (0-3 days post-delivery)\n   - For all HIV exposed infants whose mothers are on a 2nd and 3rd line regimen, Baylor should be consulted to guide appropriate infant prophylaxis. This should be planned during the antenatal period\n- Any HIV positive pregnant and breastfeeding women with a detectable viral load at contact requires URGENT intervention:\n   - 1st line with a high VL while on a non-DTG-based regimen should have an expedited switch to 2nd line DTG-based regimen on the same day\n   - 2nd line clients with a high VL should have a genotype sent on the same day and then be placed on a 3rd line holding regimen while awaiting further guidance from the HIVDR committee: snapthirdline@mohcoag.org\n- Adherence assessment, identification of barriers and necessary support should be provided within a case management framework",
   flags=[DUP], pages=list(range(27, 28+1))),
 B("box-1.2-summary-ch9", 28, HP + " > Chapter 9: ART for Children and Adolescents", "Summary of major changes: Chapter 9 (ART for Children and Adolescents)", ['0032', '0033', '0034', '0042'],
   "Chapter 9: ART for Children and Adolescents – major changes in the 2022 guidelines:\n- All HIV-infected children and adolescents are eligible for rapid ART initiation regardless of CD4 count or WHO clinical stage.\n- All children, adolescents and caregivers should be well-prepared for ART to ensure good adherence and treatment success.\n- TDF+3TC+DTG (TLD) is the preferred first-line regimen for all adolescents weighing at least 40 kg. Alternative first-line regimens are outlined in Table 7.4.\n- Prioritize assessment and rapid ART initiation in children and adolescents with advanced immunodeficiency as soon as possible (within 7 days) from the day of HIV diagnosis.\n- Paediatric >10 years of age and adolescent clients with advanced immune deficiency should be screened for cryptococcal meningitis using a serum Cryptococcal antigen (CrAg) test and TB presumptive adolescents and children should receive an LF TB-LAM test.\n- To expedite the decision-making in CALHIV, the first viral load test should be done 3 months after initiating ART then 6monthly thereafter\n- Children and adolescents with a VL > 50 copies/mL should be referred for stepped–up adherence counselling.\n- A viral load threshold of ≥1000 copies/mL should be used to determine virological failure when using plasma or dried blood spot specimens.\n- For second-line ART regimens, Atazanavir (ATV/r) is preferred over LPV/r due to its reduced pill burden. Clients can be switched from LPV/r regimens if they meet the requirements outlined in Chapter 9 Section 9.6\n- Third-line ART: Each child or adolescent should receive individualized treatment regimens based on ART history, and previous episodes of viraemia/HIV resistance testing/ genotyping results if second-line ART failure is confirmed.\n- Adolescents aged 17 to 19 years of age should be successfully transitioned to adult care. A detailed care package and checklist for a successful transition are provided in Table 9.17 To promote long-term adherence and viral suppression, all facilities must have Teen Clubs. Facilities should also have dedicated days for children, especially those that are failing treatment",
   flags=[DUP], pages=list(range(28, 29+1))),
 B("box-1.2-summary-ch10", 29, HP + " > Chapter 10: Management of HIV and Noncommunicable Diseases", "Summary of major changes: Chapter 10 (Management of HIV and Noncommunicable Diseases)", ['0035', '0036', '0043', '0044'],
   "Chapter 10: Management of HIV and Noncommunicable Diseases – major changes in the 2022 guidelines:\n- All clients infected with HIV should be routinely screened for cardiovascular risk factors, non-communicable diseases and mental health at enrolment and in subsequent visits.\n- Blood pressure should be monitored at every clinical visit.\n- Management of Hypertension in a client with HIV follows similar treatment protocols as for HIV-negative clients. However:\n   - Calcium channel inhibitors should be used with caution as they may interact with PIs producing increased serum levels of the former. Therefore, dose titration and ECG monitoring are required.\n   - Caution should also be exercised when combining diuretics with TDF by monitoring renal function that could be impaired due to added risk for interstitial nephritis.\n- A low-dose, enteric-coated aspirin 100 mg/day may be prescribed to reduce the risk of cardiovascular morbidity and mortality. Aspirin initiation should only be initiated by a doctor led service, following careful assessment of risk.\n- Annual symptom screening for diabetes mellitus and random blood sugar testing is recommended for establishing diagnosis of diabetes among PLHIV. Care and management of clients with Diabetes and HIV is described in Section 10.3\n- A high prevalence of depression is reported among PLHIV compared to the general population. Clients should be screened for depression using the PHQ9 assessment tool at initiation and every 6 months thereafter. Clients should be managed appropriately as described in Section 10.6\n- All clients should be evaluated for pain at every visit using a validated pain scale.\n- For methods and reporting on pharmacovigilance, refer to Chapter 5, Section 5.12",
   flags=[DUP], pages=list(range(29, 29+1))),
]
